class AssistantPage extends StatefulWidget { const AssistantPage({super.key}); @override State<AssistantPage> createState() => _AssistantPageState(); }
class _AssistantPageState extends State<AssistantPage> {
  final controller = TextEditingController(); final messages = <String>['Hi! I’m SANJ AI. I can help organise tasks and guide you around your personal workspace.'];
  void send() { final q = controller.text.trim(); if (q.isEmpty) return; setState(() { messages.add('You: $q'); messages.add(_reply(q)); controller.clear(); }); }
  String _reply(String q) { final s = q.toLowerCase(); if (s.contains('task') || s.contains('remind')) return 'I can help you plan that. Open My Tasks to add a task and set its due date. This starter version handles task management locally; advanced on-device AI actions are a future integration.'; if (s.contains('aadhaar') || s.contains('pan') || s.contains('passport') || s.contains('document')) return 'Your Family Vault stores imported documents securely on this device. Open the Vault tab, then search by document name or family member.'; if (s.contains('offline')) return 'SANJ AI is designed to keep your personal records on this device. The vault works offline after files are imported.'; return 'I can help you navigate your tasks, family vault, planner and goals. Some advanced conversational AI features need an on-device model integration.'; }
  @override Widget build(BuildContext context) => Column(children: [Padding(padding: const EdgeInsets.fromLTRB(18, 18, 18, 10), child: Row(children: [const Icon(Icons.auto_awesome, color: teal), const SizedBox(width: 10), const Expanded(child: Text('SANJ AI Assistant', style: TextStyle(fontSize: 21, fontWeight: FontWeight.w800, color: ink))), Container(padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6), decoration: BoxDecoration(color: const Color(0xFFE4F6F2), borderRadius: BorderRadius.circular(20)), child: const Text('LOCAL MODE', style: TextStyle(color: teal, fontSize: 9, fontWeight: FontWeight.w800, letterSpacing: 1)))])),
    Expanded(child: ListView(padding: const EdgeInsets.all(18), children: [for (final m in messages) Align(alignment: m.startsWith('You:') ? Alignment.centerRight : Alignment.centerLeft, child: Container(constraints: const BoxConstraints(maxWidth: 310), margin: const EdgeInsets.only(bottom: 12), padding: const EdgeInsets.all(15), decoration: BoxDecoration(color: m.startsWith('You:') ? navy : Colors.white, borderRadius: BorderRadius.circular(18)), child: Text(m.replaceFirst('You: ', ''), style: TextStyle(color: m.startsWith('You:') ? Colors.white : ink, height: 1.45))))])),
    Padding(padding: const EdgeInsets.fromLTRB(14, 8, 14, 14), child: Row(children: [Expanded(child: TextField(controller: controller, onSubmitted: (_) => send(), decoration: const InputDecoration(hintText: 'Ask or type a command...'))), const SizedBox(width: 8), IconButton.filled(onPressed: send, style: IconButton.styleFrom(backgroundColor: teal, foregroundColor: Colors.white), icon: const Icon(Icons.arrow_upward_rounded))]))]);
}

class TasksPage extends StatefulWidget { const TasksPage({super.key}); @override State<TasksPage> createState() => _TasksPageState(); }
class _TasksPageState extends State<TasksPage> {
  List<Map<String,dynamic>> tasks = []; bool loading = true;
  @override void initState() { super.initState(); load(); }
  Future<void> load() async { final p = await SharedPreferences.getInstance(); final raw = p.getString('sanj_tasks_v1'); if (raw != null) tasks = (jsonDecode(raw) as List).cast<Map<String,dynamic>>(); if (mounted) setState(() => loading = false); }
  Future<void> save() async { final p = await SharedPreferences.getInstance(); await p.setString('sanj_tasks_v1', jsonEncode(tasks)); }
  Future<void> addTask() async { final c = TextEditingController(); final title = await showDialog<String>(context: context, builder: (ctx) => AlertDialog(title: const Text('New task'), content: TextField(controller: c, autofocus: true, decoration: const InputDecoration(hintText: 'What needs to be done?')), actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(ctx, c.text.trim()), child: const Text('Add task'))])); if (title == null || title.isEmpty) return; setState(() => tasks.insert(0, {'title': title, 'done': false, 'created': DateTime.now().toIso8601String()})); await save(); }
  @override Widget build(BuildContext context) => Scaffold(backgroundColor: page, appBar: AppBar(title: const Text('My Tasks', style: TextStyle(fontWeight: FontWeight.w800))), floatingActionButton: FloatingActionButton.extended(onPressed: addTask, backgroundColor: teal, foregroundColor: Colors.white, icon: const Icon(Icons.add), label: const Text('New task')), body: loading ? const Center(child: CircularProgressIndicator()) : tasks.isEmpty ? const _EmptyState(icon: Icons.checklist_rounded, title: 'A clear space to start', subtitle: 'Add your first task and keep your day moving.') : ListView(padding: const EdgeInsets.fromLTRB(16, 8, 16, 100), children: [Text('${tasks.where((t) => t['done'] == true).length} of ${tasks.length} completed', style: const TextStyle(color: Color(0xFF758198), fontWeight: FontWeight.w600)), const SizedBox(height: 12), for (int i=0;i<tasks.length;i++) Card(child: CheckboxListTile(value: tasks[i]['done'] == true, activeColor: teal, title: Text(tasks[i]['title'], style: TextStyle(color: ink, decoration: tasks[i]['done'] == true ? TextDecoration.lineThrough : null)), subtitle: const Text('Saved on this device', style: TextStyle(fontSize: 11, color: Color(0xFF8490A2))), onChanged: (v) async { setState(() => tasks[i]['done'] = v ?? false); await save(); }, secondary: IconButton(onPressed: () async { setState(() => tasks.removeAt(i)); await save(); }, icon: const Icon(Icons.delete_outline, color: Color(0xFF9AA4B2)))))]));
}

